style.css:
/* Hace que las imágenes de accesos directos se vean como burbujas */
a[href*="http"] img {
  border-radius: 50% !important; /* redondea la imagen */
  box-shadow: 0 4px 10px rgba(0,0,0,0.2); /* agrega sombra */
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

/* Efecto al pasar el mouse encima */
a[href*="http"] img:hover {
  transform: scale(1.1); /* se agranda como burbuja */
  box-shadow: 0 6px 15px rgba(0,0,0,0.3);
}
